                  beq x9, x21, pt_fault_handler
                  li x21, 0xf
                  beq x9, x21, pt_fault_handler
                  li x21, 0x2 # ILLEGAL_INSTRUCTION
                  beq x9, x21, illegal_instr_handler
                  csrr x21, 0x343 # MTVAL
                  1: la x14, test_done
                  jalr x1, x14, 0

